#!/usr/bin/env node
/**
 * Run LOCALLY, outside the public GitHub repository, against a JSON report
 * generated by Lenovo QA Status Reporting Agent. No Jira login or network calls.
 *
 * node normalize-agent-report.mjs C:\path\to\agent-report.json C:\private\dashboard-report.json
 *
 * This tool is intentionally conservative: if the input format is unrecognized,
 * it stops rather than silently reporting misleading counts.
 */
import fs from 'node:fs';
import path from 'node:path';
const [input,output]=process.argv.slice(2);
if(!input||!output){console.error('Usage: node normalize-agent-report.mjs INPUT.json OUTPUT.json');process.exit(2)}
const raw=JSON.parse(fs.readFileSync(input,'utf8'));
const buckets={qa:['QA','Internal QA','QA/Testing'],review:['Review'],inProgress:['In Progress'],toDo:['To Do'],done:['Done'],closed:['Closed']};
const match=k=>Object.keys(buckets).find(b=>buckets[b].some(x=>x.replace(/\W/g,'').toLowerCase()===String(k).replace(/\W/g,'').toLowerCase()));
const zero=()=>Object.fromEntries(Object.keys(buckets).map(k=>[k,0]));
const normalizeTicket=(t,owner,project,status)=>{const fields=t?.fields||{};if(!/^[A-Z][A-Z0-9_]*-\d+$/.test(t?.key||''))return null;return {key:t.key,summary:String(t.summary||fields.summary||''),status:t.status?.name||fields.status?.name||status,owner,project,updated:t.updated||fields.updated||null}};
const source=raw.report||raw;
let entries=[];
if(Array.isArray(source.entries)){
 entries=source.entries.map(e=>({name:e.name,project:e.project,counts:e.counts,tickets:e.tickets||[]}));
}else if(Array.isArray(source.issues)){
 const groups=new Map();
 for(const issue of source.issues){
  const fields=issue.fields||{};
  const project=issue.project?.key||fields.project?.key||issue.project;
  const owner=issue.qaOwner||issue.reviewer?.displayName||fields.reviewer?.displayName||fields.assignee?.displayName||issue.assignee?.displayName;
  const status=issue.status?.name||fields.status?.name||issue.status;
  const bucket=match(status);
  if(!project||!owner||!bucket)continue;
  const id=owner+'::'+project;
  if(!groups.has(id))groups.set(id,{name:owner,project,counts:zero(),tickets:[]});
  const g=groups.get(id);g.counts[bucket]++;
  const t=normalizeTicket(issue,owner,project,status);if(t)g.tickets.push(t);
 }
 entries=[...groups.values()];
}else{
 for(const [owner,projects] of Object.entries(source)){
  if(['capturedAt','generatedAt','metadata','summary','totals','teamTotals','users'].includes(owner)||!projects||typeof projects!=='object'||Array.isArray(projects))continue;
  for(const [project,states] of Object.entries(projects)){
   if(!states||typeof states!=='object'||Array.isArray(states))continue;
   const counts=zero(),tickets=[];
   for(const [status,value] of Object.entries(states)){
    const bucket=match(status);if(!bucket)continue;
    if(Array.isArray(value)){counts[bucket]+=value.length;for(const item of value){const t=normalizeTicket(item,owner,project,status);if(t)tickets.push(t)}}
    else if(Number.isSafeInteger(value)&&value>=0)counts[bucket]+=value;
    else if(value&&Number.isSafeInteger(value.count)&&value.count>=0)counts[bucket]+=value.count;
   }
   entries.push({name:owner,project,counts,tickets});
  }
 }
}
entries=entries.filter(e=>e.name&&e.project&&e.counts&&Object.values(e.counts).some(v=>Number(v)>0));
if(!entries.length){console.error('Input format not recognized or no QA records. Please inspect the agent output schema before mapping.');process.exit(1)}
const result={capturedAt:raw.capturedAt||raw.generatedAt||new Date().toISOString(),entries};
const dest=path.resolve(output);
fs.mkdirSync(path.dirname(dest),{recursive:true});
fs.writeFileSync(dest,JSON.stringify(result,null,2),'utf8');
console.log('Created local report:',dest,'with',entries.length,'QA/project records. DO NOT COMMIT IT TO GITHUB.');
